ABSTRACT_TH = [
    ("p", "งานนี้เสนอ EGAT-MAPPO สำหรับการจัดสรรช่องสัญญาณร่วมกับการเลือกเส้นทางในเครือข่าย Wi-Fi Mesh แบบหลาย hop แต่ละโหนดเป็นตัวแทนที่เลือกช่อง downlink และโหนดแม่ของตนเอง แบบจำลองใช้ GATv2 ที่รับคุณลักษณะของขอบ หัวตัดสินใจสองช่วงเวลา และ residual prior จากวิธี local cost ของ Ko ฝึกด้วย behaviour cloning ตามด้วย MAPPO และใช้ switch hysteresis ขณะใช้งานแบบกระจายศูนย์ ประเมินบนสภาพแวดล้อมจำลอง 20 โหนด 6 ช่อง ใน 11 สถานการณ์ เทียบกับ M0, Ko, Q-neutral, Yuan (GAT+DQN) และ Li (GAT-A2C) ด้วยคะแนนรวมห้าตัวชี้วัดที่กำหนดไว้ล่วงหน้า ในสภาวะหลักบน topology ทดสอบ EGAT-MAPPO มีคะแนนรวมเฉลี่ยสูงกว่าทุกวิธีเกิน 10% (Ko +19.5%, Li +16.0%, Yuan +25.6%) อย่างมีนัยสำคัญ และบน topology ใหม่ยังสูงกว่า Ko +15.1% แต่ส่วนใหญ่ของข้อได้เปรียบเหนือ Ko มาจากการสลับที่น้อยลง (throughput +6.5%) เมื่อให้คู่เทียบใช้ hysteresis เดียวกัน ส่วนต่างเหลือ 4–8%"),
    ("p", "คำสำคัญ  การจัดสรรช่องสัญญาณ  การเลือกเส้นทาง  Graph attention  MAPPO  Wi-Fi Mesh"),
]

ABSTRACT_EN = [
    ("p", "We propose EGAT-MAPPO for joint channel assignment and routing in multi-hop Wi-Fi mesh networks. Every node is an agent that chooses its downlink channel and its parent. The model combines an edge-aware GATv2 encoder, two decision timescales and a residual prior from Ko's local-cost rule; it is warm-started by behaviour cloning, trained with MAPPO and executed in a decentralised way with switch hysteresis. In a 20-node, six-channel simulator over 11 scenarios, we compare it with M0, Ko, Q-neutral, Yuan (GAT+DQN) and Li (GAT-A2C) on a five-metric composite fixed before the main experiments. In the main setting on the test topologies, its mean composite exceeds every adapted baseline by more than 10% (Ko +19.5%, Li +16.0%, Yuan +25.6%), significantly above zero; on fresh topologies it still improves on Ko by 15.1%. Most of the gain over Ko comes from fewer switches (throughput +6.5%); with the same hysteresis for Li and Yuan the margin falls to 4-8%."),
    ("p", "Keywords  Channel assignment  Routing  Graph attention  MAPPO  Wi-Fi mesh"),
]

